#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
set -euo pipefail

fibonacci() {
    local n="$1" a=0 b=1 i tmp
    printf 'First %s terms of the Fibonacci sequence:\n' "$n"
    for ((i = 0; i < n; i++)); do
        printf '%s ' "$a"
        tmp=$((a + b)); a=$b; b=$tmp
    done
    printf '\n'
}

fibonacci {{N}}